def urljoin_(base, url):
    """
    Reproduce urllib.parse.urljoin following RFC 3986 reference resolution.
    """

    def parse_url(url):
        """Parse a URL into components: scheme, authority, path, query, fragment."""
        scheme = None
        authority = None
        path = ""
        query = None
        fragment = None

        # Extract fragment
        if '#' in url:
            url, fragment = url.rsplit('#', 1)

        # Extract query
        if '?' in url:
            url, query = url.split('?', 1)

        # Extract scheme
        if '://' in url:
            idx = url.index('://')
            scheme = url[:idx]
            url = url[idx+3:]
            # Extract authority (everything before the first '/')
            if '/' in url:
                authority, path = url.split('/', 1)
                path = '/' + path
            else:
                authority = url
                path = ""
        elif url.startswith('//'):
            # Scheme-relative: //host/path
            rest = url[2:]
            if '/' in rest:
                authority, path = rest.split('/', 1)
                path = '/' + path
            else:
                authority = rest
                path = ""
            scheme = None  # Will be filled from base later
        elif url.startswith('/'):
            path = url
        elif url == "":
            path = ""
        else:
            path = url

        return scheme, authority, path, query, fragment

    def remove_dot_segments(path):
        """Remove '.' and '..' segments from a path per RFC 3986 section 5.2.4."""
        # Input: a path string
        # Output: a normalized path string

        output = []
        # Split into segments
        if path.startswith('/'):
            input_segments = path[1:].split('/')
            starts_with_slash = True
        else:
            input_segments = path.split('/')
            starts_with_slash = False

        for seg in input_segments:
            if seg == '.':
                continue
            elif seg == '..':
                if output:
                    output.pop()
            else:
                output.append(seg)

        if starts_with_slash:
            result = '/' + '/'.join(output)
        else:
            result = '/'.join(output)

        # Ensure trailing slash if original path ended with '/' or last segment was '.' or '..'
        # Actually, per RFC, we need to handle trailing slash carefully
        # If the original path ended with '/', '.', or '..', the output should end with '/'
        if path.endswith('/') or path.endswith('/.') or path.endswith('/..'):
            if result and not result.endswith('/'):
                result += '/'
            elif not result and starts_with_slash:
                result = '/'

        return result

    def merge_paths(base_path, ref_path):
        """Merge base path with reference path per RFC 3986 section 5.2.3."""
        if base_path == "":
            return '/' + ref_path if ref_path else '/'

        # Find the last '/' in base_path
        idx = base_path.rfind('/')
        if idx >= 0:
            return base_path[:idx+1] + ref_path
        else:
            return '/' + ref_path

    # Parse both URLs
    base_scheme, base_authority, base_path, base_query, base_fragment = parse_url(base)
    ref_scheme, ref_authority, ref_path, ref_query, ref_fragment = parse_url(url)

    # If url is empty, return base without fragment
    if url == "":
        result = base
        if '#' in result:
            result = result.split('#', 1)[0]
        return result

    # Determine components per RFC 3986 section 5.2.2

    if ref_scheme is not None:
        # Absolute URL with scheme: use ref components
        scheme = ref_scheme
        authority = ref_authority
        path = remove_dot_segments(ref_path)
        query = ref_query
    elif ref_authority is not None:
        # Scheme-relative reference: use base scheme, ref authority and path
        scheme = base_scheme
        authority = ref_authority
        path = remove_dot_segments(ref_path)
        query = ref_query
    elif ref_path == "":
        # No path in reference
        if ref_query is not None:
            # Query-only reference
            authority = base_authority
            path = base_path
            query = ref_query
        elif ref_fragment is not None:
            # Fragment-only reference
            authority = base_authority
            path = base_path
            query = base_query
        else:
            # Empty reference handled above, but just in case
            authority = base_authority
            path = base_path
            query = base_query
    elif ref_path.startswith('/'):
        # Absolute path reference
        authority = base_authority
        path = remove_dot_segments(ref_path)
        query = ref_query
    else:
        # Relative path reference
        authority = base_authority
        merged_path = merge_paths(base_path, ref_path)
        path = remove_dot_segments(merged_path)
        query = ref_query

    # Handle fragment
    if ref_fragment is not None:
        fragment = ref_fragment
    elif url == "":
        fragment = None
    else:
        # If no fragment in ref and url is not empty, fragment is None (per RFC, 
        # but actually if ref has no fragment and ref is not empty, we don't carry base fragment)
        fragment = None

    # Reconstruct the URL
    result = ""
    if scheme:
        result += scheme + ":"
    if authority is not None:
        result += "//" + authority
    if path:
        if not path.startswith('/') and authority is not None:
            result += '/' + path
        else:
            result += path
    elif authority is not None:
        # Path is empty but authority exists
        pass

    if query is not None:
        result += '?' + query
    if fragment is not None:
        result += '#' + fragment

    return result
