def urljoin_(base, url):
    """Reproduce urllib.parse.urljoin from scratch, implementing RFC 3986 reference resolution."""

    def _parse(url):
        """Parse a URL into components: scheme, netloc, path, query, fragment."""
        # Extract fragment
        if '#' in url:
            idx = url.index('#')
            fragment = url[idx + 1:]
            url = url[:idx]
        else:
            fragment = ''

        # Extract query
        if '?' in url:
            idx = url.index('?')
            query = url[idx + 1:]
            url = url[:idx]
        else:
            query = ''

        # Extract scheme
        scheme = ''
        if url.startswith('//'):
            # scheme-relative: no scheme, netloc starts after //
            scheme = ''
            # netloc is the part before the first / after //
            rest = url[2:]
            if '/' in rest:
                idx = rest.index('/')
                netloc = rest[:idx]
                path = rest[idx:]
            else:
                netloc = rest
                path = ''
            return scheme, netloc, path, query, fragment

        # Check for scheme (followed by :// or just :)
        colon_idx = url.find(':')
        if colon_idx > 0:
            # Validate scheme: must start with alpha, followed by alpha/digit/+/-/.
            candidate = url[:colon_idx]
            if candidate and candidate[0].isalpha():
                valid = True
                for c in candidate[1:]:
                    if not (c.isalnum() or c in '+-.'):
                        valid = False
                        break
                if valid and url[colon_idx + 1:].startswith('//'):
                    scheme = candidate
                    rest = url[colon_idx + 3:]
                    if '/' in rest:
                        idx = rest.index('/')
                        netloc = rest[:idx]
                        path = rest[idx:]
                    else:
                        netloc = rest
                        path = ''
                    return scheme, netloc, path, query, fragment
                elif valid:
                    # scheme:path without // (e.g., mailto:user@example.com)
                    scheme = candidate
                    rest = url[colon_idx + 1:]
                    # For schemes like mailto, there's no netloc
                    # We'll treat it as scheme with path
                    return scheme, '', rest, query, fragment

        # No scheme found
        scheme = ''
        if url.startswith('/'):
            netloc = ''
            path = url
        else:
            netloc = ''
            path = url

        return scheme, netloc, path, query, fragment

    def _remove_dot_segments(path):
        """Remove . and .. segments from a path per RFC 3986 section 5.2.4."""
        output = []
        while path:
            if path.startswith('./'):
                path = path[2:]
            elif path.startswith('../'):
                path = path[3:]
                if output:
                    output.pop()
            elif path == '.':
                path = ''
            elif path == '..':
                path = ''
                if output:
                    output.pop()
            elif path.startswith('/./'):
                path = '/' + path[3:]
            elif path.startswith('/../'):
                path = '/' + path[4:]
                if output:
                    output.pop()
            elif path == '/.':
                path = '/'
            elif path == '/..':
                path = '/..'
                if output:
                    output.pop()
            else:
                if path.startswith('/'):
                    # Find next /
                    idx = path.find('/', 1)
                    if idx == -1:
                        output.append(path)
                        path = ''
                    else:
                        output.append(path[:idx])
                        path = path[idx:]
                else:
                    idx = path.find('/')
                    if idx == -1:
                        output.append(path)
                        path = ''
                    else:
                        output.append(path[:idx])
                        path = path[idx:]

        return ''.join(output)

    def _merge_paths(base_path, ref_path):
        """Merge base path and reference path per RFC 3986 section 5.2.3."""
        if base_path.startswith('/'):
            # Base has authority, merge with reference path directly
            return '/' + ref_path if ref_path else '/'
        else:
            # No authority, merge by removing last segment from base path
            idx = base_path.rfind('/')
            if idx == -1:
                return ref_path
            else:
                return base_path[:idx + 1] + ref_path

    def _rebuild(scheme, netloc, path, query, fragment):
        """Rebuild URL from components."""
        result = ''
        if scheme:
            result += scheme + ':'
        if netloc:
            result += '//' + netloc
        result += path
        if query:
            result += '?' + query
        if fragment:
            result += '#' + fragment
        return result

    # Parse base and reference
    base_scheme, base_netloc, base_path, base_query, base_fragment = _parse(base)
    ref_scheme, ref_netloc, ref_path, ref_query, ref_fragment = _parse(url)

    # Empty reference: return base without fragment
    if url == '':
        return _rebuild(base_scheme, base_netloc, base_path, base_query, '')

    # If reference has a scheme, use reference components as-is (with normalization)
    if ref_scheme:
        ref_path = _remove_dot_segments(ref_path)
        return _rebuild(ref_scheme, ref_netloc, ref_path, ref_query, ref_fragment)

    # Reference is relative to base
    if ref_netloc:
        # Scheme-relative //host/path
        ref_path = _remove_dot_segments(ref_path)
        return _rebuild(base_scheme, ref_netloc, ref_path, ref_query, ref_fragment)

    # Absolute path in reference
    if ref_path.startswith('/'):
        ref_path = _remove_dot_segments(ref_path)
        return _rebuild(base_scheme, base_netloc, ref_path, ref_query, ref_fragment)

    # Relative path in reference
    if ref_path:
        merged_path = _merge_paths(base_path, ref_path)
        merged_path = _remove_dot_segments(merged_path)
        return _rebuild(base_scheme, base_netloc, merged_path, ref_query, ref_fragment)

    # Empty path in reference
    if ref_query:
        # Query-only reference: keep base path and query, replace fragment
        return _rebuild(base_scheme, base_netloc, base_path, ref_query, ref_fragment)

    if ref_fragment:
        # Fragment-only reference: keep base path and query, replace fragment
        return _rebuild(base_scheme, base_netloc, base_path, base_query, ref_fragment)

    # Both path and query empty, fragment empty but url was not empty string
    # This happens when url is just empty string handled above, or edge cases
    # Return base without fragment
    return _rebuild(base_scheme, base_netloc, base_path, base_query, '')
