    """
    Reproduce urllib.parse.urljoin from scratch, implementing RFC 3986 reference resolution.
    """

    def split_url(u):
        """Split a URL into scheme, authority, path, query, fragment."""
        # Extract fragment
        frag = ''
        if '#' in u:
            u, frag = u.split('#', 1)

        # Extract query
        query = ''
        if '?' in u:
            u, query = u.split('?', 1)

        # Extract scheme
        scheme = ''
        if ':' in u:
            # Find the first colon that forms a valid scheme (before any slash)
            colon_pos = u.find(':')
            slash_pos = u.find('/')
            if slash_pos == -1 or colon_pos < slash_pos:
                # Check if it looks like a scheme (starts with letter, followed by letters/digits/+/-/.)
                potential_scheme = u[:colon_pos]
                if potential_scheme and potential_scheme[0].isalpha() and all(
                    c.isalnum() or c in '+-.' for c in potential_scheme
                ):
                    scheme = potential_scheme
                    u = u[colon_pos + 1:]

        # Extract authority
        authority = ''
        if u.startswith('//'):
            # Scheme-relative or absolute with authority
            u = u[2:]
            # Find the end of authority (next /, ?, or #)
            end_idx = len(u)
            for i, c in enumerate(u):
                if c in '/?#':
                    end_idx = i
                    break
            authority = u[:end_idx]
            u = u[end_idx:]
        elif scheme and u.startswith('//'):
            # Already handled above
            pass

        return scheme, authority, u, query, frag

    def remove_dot_segments(path):
        """Remove dot segments from a path per RFC 3986 section 5.2.4."""
        output = []
        while path:
            if path.startswith('./'):
                path = path[2:]
            elif path.startswith('../'):
                path = path[3:]
                if output:
                    output.pop()
            elif path == '.' or path == '..':
                path = ''
            elif path.startswith('/./'):
                path = '/' + path[3:]
            elif path.startswith('/../'):
                path = '/' + path[4:]
                if output:
                    output.pop()
            elif path == '.':
                path = ''
            elif path == '..':
                path = ''
            else:
                # Move first path segment to output
                slash_pos = path.find('/', 1)
                if slash_pos == -1:
                    output.append(path)
                    path = ''
                else:
                    output.append(path[:slash_pos])
                    path = path[slash_pos:]
        return ''.join(output)

    def merge_paths(base_authority, base_path, ref_path):
        """Merge paths per RFC 3986 section 5.2.3."""
        if base_authority and not base_path:
            return '/' + ref_path
        else:
            last_slash = base_path.rfind('/')
            if last_slash == -1:
                return ref_path
            else:
                return base_path[:last_slash + 1] + ref_path

    # Split base and reference
    base_scheme, base_authority, base_path, base_query, base_frag = split_url(base)
    ref_scheme, ref_authority, ref_path, ref_query, ref_frag = split_url(url)

    # If reference has a scheme, it's absolute — use it entirely (but strip nothing from ref)
    if ref_scheme:
        scheme = ref_scheme
        authority = ref_authority
        path = remove_dot_segments(ref_path)
        query = ref_query
        frag = ref_frag
    else:
        # No scheme in reference
        if ref_authority:
            # Scheme-relative: //host/path
            scheme = base_scheme
            authority = ref_authority
            path = remove_dot_segments(ref_path)
            query = ref_query
            frag = ref_frag
        elif not ref_path:
            if not ref_query:
                # Empty path and empty query: use base path and query, but with new fragment
                scheme = base_scheme
                authority = base_authority
                path = base_path
                query = base_query
                frag = ref_frag
            else:
                # Query-only reference: use base path with new query
                scheme = base_scheme
                authority = base_authority
                path = base_path
                query = ref_query
                frag = ref_frag
        elif ref_path.startswith('/'):
            # Absolute path
            scheme = base_scheme
            authority = base_authority
            path = remove_dot_segments(ref_path)
            query = ref_query
            frag = ref_frag
        else:
            # Relative path
            scheme = base_scheme
            authority = base_authority
            path = remove_dot_segments(merge_paths(base_authority, base_path, ref_path))
            query = ref_query
            frag = ref_frag

    # Reconstruct the URL
    result = ''
    if scheme:
        result += scheme + ':'
    if authority:
        result += '//' + authority
    if path:
        result += path
    if query:
        result += '?' + query
    if frag:
        result += '#' + frag

    return result
